            $terms=get_terms(['taxonomy'=>$taxonomy,'hide_empty'=>false,'number'=>41,'orderby'=>'term_id','order'=>'ASC']);if(is_wp_error($terms)){self::invalid();}$termsTruncated=count($terms)>40;foreach(array_slice($terms,0,40)as$term){if(!self::plain($term->name)){$termsTruncated=true;continue;}$termRows[]=['term_id'=>(int)$term->term_id,'name'=>$term->name];}}
